    const __m128 inf_inf_k = _mm_set_ps(0.0f, 0.0f, std::numeric_limits<float>::infinity(), std::numeric_limits<float>::infinity());
    const __m128 wu_wn = detail::blend(gu_gn, inf_inf_k, su_sn);
